import core/trusted/layer_declaration
axiomLayer "gate"
{.push raises: [].}

## self_ref_detect.nim — Compile-time self-referential change detection.
## Detects when staged git changes include files that are part of the
## bin/axiom-gate binary, to trigger bootstrap mode.
##
## Uses slurp() to read build_metadata.json at compile time (same pattern
## as gate_registry.nim reads _index.json). New modules are automatically
## included when build_metadata.json is regenerated by bin/hermetic_build.

import std/[json, sets, macros]

# ── Compile-time: load sourceFileList from build_metadata.json ────────
# slurp() reads the file at compile time, creating a compile-time dependency.
# When build_metadata.json changes (regenerated by hermetic_build), this
# module is recompiled automatically.
const buildMetaRaw = slurp("src/generated/build_metadata.json")

macro loadBootstrapSensitivePaths(): HashSet[string] =
  ## Parse build_metadata.json at compile time and generate a HashSet
  ## of all source paths that compose the axiom-gate binary.
  ## Pattern: gate_registry.nim's loadAllGatesFromManifest() macro.
  let meta = parseJson(buildMetaRaw)
  result = newStmtList()
  let setVar = genSym(nskVar, "paths")
  result.add(quote do:
    var `setVar`: HashSet[string]
  )
  for entry in meta["sourceFileList"]:
    let path = "src/" & entry.getStr()
    result.add(quote do:
      `setVar`.incl(`path`)
    )
  result.add(quote do:
    `setVar`
  )

const BootstrapSensitivePaths*: HashSet[string] = loadBootstrapSensitivePaths()
  ## Set of source file paths that compose the bin/axiom-gate binary.
  ## Auto-populated from build_metadata.json at compile time.
  ## New modules are included when hermetic_build regenerates the metadata.

func isSelfReferentialChange*(stagedFiles: seq[string]): bool =
  ## Check if any staged file is part of the axiom-gate binary.
  ## Returns true if the commit modifies the verification kernel itself.
  for f in stagedFiles:
    if f in BootstrapSensitivePaths:
      return true
  false

func getSensitiveFiles*(stagedFiles: seq[string]): seq[string] =
  ## Return the subset of staged files that are part of the axiom-gate binary.
  result = @[]
  for f in stagedFiles:
    if f in BootstrapSensitivePaths:
      result.add(f)

when isMainModule:
  # Self-test: verify compile-time loading works
  echo "Bootstrap sensitive paths loaded: ", BootstrapSensitivePaths.len, " files"
  # Test with known paths
  assert isSelfReferentialChange(@["src/core/gateway/gateway.nim"]) == true
  assert isSelfReferentialChange(@["docs/README.md"]) == false
  assert isSelfReferentialChange(@["src/gate/orchestrator/hook/executor.nim"]) == true
  echo "All self-ref detection tests passed"

{.pop.}
